/* STT-SERVIS: company identity and service-led homepage. */
function brandHome(){
 const taskRows=[['trench','Траншеи и земляные работы','Под коммуникации, дренаж и подготовку основания.'],['level','Планировка территории','Грунт, песок и щебень. Подготовка и выравнивание.'],['drill','Бурение и работы со сваями','Ямобур, подбор диаметра и необходимой глубины.'],['demolition','Демонтаж бетона и асфальта','Мини-экскаватор с гидромолотом под объём работ.']];
 return `<section class="stt-hero"><div class="stt-hero-photo"><img src="${A}104.jpg" alt="Мини-экскаватор Kubota из каталога СТТ-Сервис" fetchpriority="high" width="1500" height="1000"></div><div class="wrap stt-hero-content"><div class="stt-location"><span></span>Москва и Московская область</div><h1>Аренда<br>спецтехники<span>с оператором</span></h1><p>Мини-экскаваторы, погрузчики и навесное оборудование. Подберём машину под ваш объект и согласуем доставку.</p><div class="stt-hero-actions">${link('Посмотреть технику','/catalog/')}${button('Помочь с подбором','data-picker','outline')}</div><div class="stt-hero-details"><div><b>8 часов</b><span>минимальная смена</span></div><div><b>По договору</b><span>для частных лиц и компаний</span></div><div><b>Под задачу</b><span>машина и оборудование</span></div></div></div><div class="stt-photo-caption"><span>Мини-экскаваторы</span><b>Компактность. Манёвренность. Точность.</b></div></section>
 <nav class="stt-direction-strip" aria-label="Основные направления"><div class="wrap"><a href="/catalog/?group=mini"><span class="stt-strip-icon">${machineIcon('excavator')}</span><span><b>Мини-экскаваторы</b><small>Земляные работы и демонтаж</small></span>${arrow}</a><a href="/catalog/?group=loader"><span class="stt-strip-icon">${machineIcon('loader')}</span><span><b>Мини-погрузчики</b><small>Материалы и планировка</small></span>${arrow}</a><a href="/catalog/?group=attachment"><span class="stt-strip-icon">${machineIcon('attachment')}</span><span><b>Навесное оборудование</b><small>Ямобур, гидромолот, вилы</small></span>${arrow}</a><a href="/services/transport/"><span class="stt-strip-icon">${machineIcon('truck')}</span><span><b>Грузоперевозки</b><small>Грузы и спецтехника</small></span>${arrow}</a></div></nav>
 <section class="section stt-catalog" id="fleet"><div class="wrap"><div class="stt-section-head reveal"><div><span class="stt-kicker">Каталог СТТ-Сервис</span><h2>Техника в аренду</h2></div><div><p>Сравните рабочие параметры.<br>Нужный вариант согласуем на вашу дату.</p><a class="textlink" href="/catalog/">Открыть каталог ${arrow}</a></div></div><div class="tabs" role="tablist" aria-label="Категории техники"><button class="tab active" role="tab" aria-selected="true" data-fleet="mini">Мини-экскаваторы</button><button class="tab" role="tab" aria-selected="false" data-fleet="loader">Мини-погрузчики</button><button class="tab" role="tab" aria-selected="false" data-fleet="attachment">С навесным оборудованием</button></div><div class="machine-grid" id="home-fleet" role="tabpanel">${machines.filter(m=>m.group==='mini').map(card).join('')}</div><div class="stt-catalog-bottom"><p>Тарифы из опубликованного каталога. Доставка, оборудование и итоговая стоимость уточняются при заказе.</p><a href="/conditions/">Все условия аренды ${arrow}</a></div></div></section>
 <section class="section stt-object" id="tasks"><div class="wrap stt-object-grid"><div class="stt-object-visual reveal"><img src="${A}62_1.webp" alt="Компактный экскаватор рядом с постройкой" loading="lazy" width="1500" height="1055"><div class="stt-object-note"><span>Для ограниченного пространства</span><b>Проезд от 1,3 м</b><small>У мини-экскаватора категории 2 т.<br>Габариты выбранной машины подтвердим.</small></div></div><div class="stt-object-copy reveal"><span class="stt-kicker">Подбор под условия объекта</span><h2>Нужна техника<br>для вашего участка?</h2><p>Учитываем ширину проезда, грунт, глубину работ и необходимое оборудование. Сообщите известные детали — остальное уточним вместе.</p><form id="quick-pick" class="stt-quick-form"><label class="form-field"><span>Задача</span><select name="task"><option value="trench">Земляные работы / траншея</option><option value="level">Планировка участка</option><option value="drill">Бурение отверстий</option><option value="demolition">Работы гидромолотом</option><option value="loading">Погрузка материалов</option><option value="other">Нужна консультация</option></select></label><label class="form-field"><span>Где находится объект?</span><input name="location" required placeholder="Город, посёлок или адрес" autocomplete="street-address"></label>${button('Обсудить подбор','type="submit"')}<p class="form-hint">Подготовим запрос для отправки в Telegram или по почте.</p></form></div></div></section>
 <section class="section stt-tasks"><div class="wrap"><div class="stt-section-head reveal"><div><span class="stt-kicker">Работы на объекте</span><h2>Что нужно выполнить?</h2></div><p>Можно начать с задачи —<br>название машины знать необязательно.</p></div><div class="stt-task-grid">${taskRows.map(([id,title,desc])=>`<a class="stt-task-card reveal" href="/tasks/${id}/"><span class="stt-task-symbol">${machineIcon(id==='drill'?'attachment':id==='level'?'loader':'excavator')}</span><div><h3>${title}</h3><p>${desc}</p></div>${arrow}</a>`).join('')}</div><div class="stt-more-tasks"><a href="/tasks/loading/">Погрузка и перемещение материалов ${arrow}</a><a href="/tasks/clean/">Уборка и обслуживание территории ${arrow}</a></div></div></section>
 <section class="section stt-services" id="services"><div class="wrap"><div class="stt-section-head reveal"><div><span class="stt-kicker">Другие направления</span><h2>Перевозки, обслуживание<br>и подготовка территории</h2></div><p>Обсудим состав работ,<br>необходимую технику и условия.</p></div><div class="stt-service-grid">${Object.entries(services).map(([id,s])=>`<a class="stt-service-card reveal" href="/services/${id}/"><img src="${A+s.photo}" alt="" loading="lazy"><div><span>${id==='transport'?'Транспорт':id==='landscape'?'Территория':id==='repair'?'Сервис':'Комплектующие'}</span><h3>${s.name}</h3><p>${id==='transport'?'Подбор транспорта по массе, габаритам и маршруту.':id==='landscape'?'Планировка, перемещение материалов и покос.':id==='repair'?'Обслуживание строительной техники и грузовиков.':'Фильтры, компоненты двигателей и трансмиссии.'}</p><span class="stt-service-link">Подробнее ${arrow}</span></div></a>`).join('')}</div></div></section>
 <section class="section stt-work"><div class="wrap"><div class="stt-section-head reveal"><div><span class="stt-kicker">Техника в работе</span><h2>Оборудование для разных задач</h2></div><a class="textlink" href="/work/">Все фотографии ${arrow}</a></div><div class="stt-work-grid"><a class="stt-work-tile stt-work-large reveal" href="/tasks/trench/"><img src="${A}36c.jpg" alt="Мини-экскаватор на земляных работах" loading="lazy"><div><small>Мини-экскаватор</small><h3>Земляные работы<br>на небольшом участке</h3>${arrow}</div></a><a class="stt-work-tile reveal" href="/tasks/drill/"><img src="${A}77.webp" alt="Экскаватор с ямобуром" loading="lazy"><div><small>Навесное оборудование</small><h3>Бурение ямобуром</h3>${arrow}</div></a><a class="stt-work-tile reveal" href="/tasks/loading/"><img src="${A}92.webp" alt="Погрузчик перемещает блоки" loading="lazy"><div><small>Мини-погрузчик</small><h3>Погрузка материалов</h3>${arrow}</div></a></div><p class="work-source">Фото из материалов СТТ-Сервис показывают применение техники. Конкретная модель и оборудование согласуются при заказе.</p></div></section>
 <section class="section stt-about"><div class="wrap stt-about-grid"><div class="stt-identity reveal"><img src="${A}telegram-avatar.jpg" alt="Оригинальный знак STT-SERVIS из Telegram" width="220" height="220" loading="lazy"><strong>STT-SERVIS</strong><span>Аренда спецтехники<br>Москва и Московская область</span></div><div class="stt-about-copy reveal"><span class="stt-kicker">О компании</span><h2>Прямой контакт.<br>Внимание к вашему заказу.</h2><p>СТТ-Сервис — небольшая команда, объединённая работой со спецтехникой. Уточняем задачу и особенности объекта, подбираем оборудование и согласуем условия до подачи машины.</p><div class="stt-about-facts"><div>${machineIcon('excavator')}<span>Техника<br>с оператором</span></div><div>${machineIcon('truck')}<span>Организация<br>доставки</span></div><div>${documentIcon()}<span>Договор<br>и формы оплаты</span></div></div><a class="textlink" href="/company/">Подробнее о компании ${arrow}</a></div></div></section>
 <section class="section stt-process"><div class="wrap"><div class="stt-section-head reveal"><div><span class="stt-kicker">Порядок заказа</span><h2>От обращения до подачи техники</h2></div></div><div class="stt-process-grid"><div><span>01</span><h3>Обсуждаем задачу</h3><p>Место работ, объём, проезд и желаемая дата.</p></div><div><span>02</span><h3>Согласуем заказ</h3><p>Машина, оборудование, стоимость и документы.</p></div><div><span>03</span><h3>Организуем подачу</h3><p>Маршрут доставки и условия доступа на объект.</p></div></div></div></section>
 ${faq()}${contactBanner()}`;
}
function machineIcon(type){const paths={excavator:'M4 32h22l5 7H4zM10 31V19h13v12M21 20 32 6l15 12-3 14-8-2M6 40h24',loader:'M6 32h25l4 7H6zM11 30V15h14l5 15M31 25l12-4 4 15H34M8 40h23',truck:'M3 14h28v21H3zM31 22h9l7 8v5H31M10 35a4 4 0 1 0 0 8 4 4 0 0 0 0-8M37 35a4 4 0 1 0 0 8 4 4 0 0 0 0-8',attachment:'M6 7h15l12 13M29 18h8v20M25 27l16-4M25 34l16-4M25 41l16-4M32 38v8'};return `<svg viewBox="0 0 50 50" aria-hidden="true"><path d="${paths[type]||paths.excavator}" stroke-linejoin="round" stroke-linecap="round"/></svg>`;}
function documentIcon(){return '<svg viewBox="0 0 50 50" aria-hidden="true"><path d="M12 5h19l8 9v31H12zM31 5v10h8M19 23h13M19 30h13M19 37h8"/></svg>';}
